1646	export function executeWorkflow(workflow, input = {}) {
1647	  const nodes = validateWorkflow(workflow);
1648	  // Business operations are asynchronous: the synchronous entry must refuse
1649	  // a workflow that names any before a single node executes.
1650	  for (const node of nodes.values()) {
1651	    const binding = actionBindings.get(node);
1652	    if (binding && binding.name !== null) {
1653	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
