1686	// context, trace and attempt records produced so far, and never carries a
1687	// success result. Compensation for already-succeeded actions is attached by
1688	// withCompensation under the usual rules.
1689	function cancelledResult(state) {
1690	  return {
1691	    status: 'cancelled',
1692	    context: state.context,
1693	    trace: state.trace,
1694	    actionAttempts: state.actionAttempts,
1695	  };
1696	}
1697	
1698	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1699	  const signal = resolveRunSignal(options);
1700	  const nodes = validateWorkflow(workflow);
1701	  verifyOperations(nodes, operations);
1702	
1703	  const state = createRunState(nodes, workflow, input);
1704	
1705	  // A signal that is already aborted stops the run before the first node —
1706	  // but only after the definition and the operation registrations above have
1707	  // been checked. Nothing executes and nothing is compensated.
1708	  if (signal && signal.aborted) {
1709	    return withCompensation(cancelledResult(state), state, operations);
1710	  }
1711	
1712	  for (;;) {
1713	    // Once the signal fires, no new regular node runs and no new business
1714	    // action attempt starts; the run ends cancelled with whatever state it
1715	    // reached, even if an end node was already visited on another branch.
1716	    if (signal && signal.aborted) {
1717	      return withCompensation(cancelledResult(state), state, operations);
1718	    }
