5	// trigger -> a (business, compensable) -> done; used through the async entry
6	function businessWorkflow(actionProps = {}) {
7	  return {
8	    id: 'shared-input',
9	    entry: 'start',
10	    nodes: [
11	      { id: 'start', type: 'trigger', next: 'a' },
12	      {
13	        id: 'a', type: 'action', operation: 'opA',
14	        compensation: { operation: 'undoA' },
15	        ...actionProps,
16	        next: 'done',
17	      },
18	      { id: 'done', type: 'end', result: 'finished' },
19	    ],
20	  };
21	}
22	
23	// trigger -> done; usable through the synchronous entry
24	function legacyWorkflow() {
25	  return {
26	    id: 'legacy-input',
27	    entry: 'start',
28	    nodes: [
29	      { id: 'start', type: 'trigger', next: 'done' },
30	      { id: 'done', type: 'end', result: 'finished' },
31	    ],
32	  };
33	}
34	
35	const ZERO_DELAY_RETRY = { attempts: 2, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
36	
37	function assertInputSharedMemoryError(error) {
38	  assert.ok(error instanceof TypeError, 'the rejection must be a TypeError');
39	  assert.match(error.message, /run input contains shared memory/);
40	  assert.match(error.message, /SharedArrayBuffer/);
41	  assert.match(error.message, /independent copies cannot be guaranteed/);
42	}
43	
44	function expectSyncReject(input) {
45	  try {
46	    executeWorkflow(legacyWorkflow(), input);
47	    assert.fail('executeWorkflow was expected to throw');
48	  } catch (error) {
49	    assertInputSharedMemoryError(error);
50	  }
51	}
52	
53	// The containers below each carry shared memory in content the input clone
54	// actually retains.
55	function sharedInputs() {
56	  const cyclic = () => {
57	    const value = { label: 'self' };
58	    value.myself = value;
59	    value.shared = new SharedArrayBuffer(2);
60	    return value;
61	  };
62	  const aliased = () => {
63	    const shared = new SharedArrayBuffer(2);
64	    const holder = { buffer: shared };
65	    return { a: holder, b: holder, list: [shared] };
66	  };
67	  const causeIsNonEnumerable = () => {
68	    const error = new Error('wrap', { cause: new Uint8Array(new SharedArrayBuffer(2)) });
69	    // The Error constructor installs "cause" as a non-enumerable own property;
70	    // it must still count because the clone retains it.
71	    assert.equal(Object.getOwnPropertyDescriptor(error, 'cause').enumerable, false);
72	    return error;
73	  };
74	  return [
75	    () => new SharedArrayBuffer(4),
76	    () => new Uint8Array(new SharedArrayBuffer(4)),
77	    () => new Int32Array(new SharedArrayBuffer(8)),
78	    () => new Float64Array(new SharedArrayBuffer(8)),
79	    () => new BigInt64Array(new SharedArrayBuffer(8)),
80	    () => new DataView(new SharedArrayBuffer(4)),
81	    () => new Uint8Array(new SharedArrayBuffer(8), 2, 3),
82	    () => ({ inner: { bytes: new SharedArrayBuffer(4) } }),
83	    () => ({ list: [1, [2, new Uint8Array(new SharedArrayBuffer(4))]] }),
84	    () => new Map([['k', new SharedArrayBuffer(4)]]),
85	    () => new Map([[new SharedArrayBuffer(4), 'k']]),
86	    () => new Map([['k', { view: new DataView(new SharedArrayBuffer(4)) }]]),
87	    () => new Set([new SharedArrayBuffer(4)]),
88	    () => new Set([{ bytes: new Uint8Array(new SharedArrayBuffer(4)) }]),
89	    () => ({ table: new Map([[new Set([new SharedArrayBuffer(4)]), new DataView(new SharedArrayBuffer(4))]]) }),
90	    causeIsNonEnumerable,
91	    cyclic,
92	    aliased,
93	  ];
94	}
95	
96	// ---------------------------------------------------------------------------
97	// The synchronous entry throws a TypeError; the asynchronous one rejects
98	// ---------------------------------------------------------------------------
99	
100	test('the synchronous entry throws a TypeError for shared-memory input before any node runs', () => {
101	  for (const make of sharedInputs()) {
102	    expectSyncReject(make());
103	  }
104	});
105	
106	test('the asynchronous entry rejects with the same TypeError and makes no business or compensation call', async () => {
107	  let businessCalls = 0;
108	  let compensationCalls = 0;
109	  const operations = {
110	    opA: () => { businessCalls += 1; return 'A'; },
111	    undoA: () => { compensationCalls += 1; return 'undone'; },
112	  };
113	  for (const make of sharedInputs()) {
114	    await assert.rejects(
115	      () => executeWorkflowAsync(businessWorkflow(), make(), operations),
116	      error => {
117	        assertInputSharedMemoryError(error);
118	        return true;
119	      },
120	    );
121	  }
122	  assert.equal(businessCalls, 0);
123	  assert.equal(compensationCalls, 0);
124	});
125	
126	test('an already-aborted signal does not turn the failure into a cancelled run: input rejection still wins', async () => {
127	  const controller = new AbortController();
128	  controller.abort();
129	  let businessCalls = 0;
130	  await assert.rejects(
131	    () => executeWorkflowAsync(
132	      businessWorkflow(),
133	      { bytes: new Uint8Array(new SharedArrayBuffer(4)) },
134	      { opA: () => { businessCalls += 1; return 'A'; }, undoA: () => 'u' },
135	      { signal: controller.signal },
136	    ),
137	    error => {
138	      assertInputSharedMemoryError(error);
139	      return true;
140	    },
141	  );
142	  assert.equal(businessCalls, 0);
143	});
144	
145	// ---------------------------------------------------------------------------
146	// Existing check ordering is preserved; the input check comes last
147	// ---------------------------------------------------------------------------
148	
149	test('definition, operation-registration and option errors are still reported before the input check', async () => {
150	  const sharedInput = { bytes: new SharedArrayBuffer(4) };
151	  const controller = new AbortController();
152	  controller.abort();
153	
154	  // An invalid definition wins over the shared input, on both entries — and
155	  // even when the signal was already aborted.
156	  const invalid = {
157	    id: 'bad', entry: 'start',
158	    nodes: [{ id: 'start', type: 'trigger', next: 'ghost' }],
159	  };
160	  assert.throws(
161	    () => executeWorkflow(invalid, sharedInput),
162	    /unknown destination/,
163	  );
164	  await assert.rejects(
165	    () => executeWorkflowAsync(invalid, sharedInput, {}, { signal: controller.signal }),
166	    /unknown destination/,
167	  );
168	
169	  // A missing business operation implementation wins over the shared input.
170	  await assert.rejects(
171	    () => executeWorkflowAsync(businessWorkflow(), sharedInput, {}),
172	    /action node a/,
173	  );
174	
175	  // A malformed options object / signal wins over the shared input.
176	  await assert.rejects(
177	    () => executeWorkflowAsync(businessWorkflow(), sharedInput, {
178	      opA: () => 'A', undoA: () => 'u',
179	    }, null),
180	    /options/,
181	  );
182	  await assert.rejects(
183	    () => executeWorkflowAsync(businessWorkflow(), sharedInput, {
184	      opA: () => 'A', undoA: () => 'u',
185	    }, { signal: 'not-a-signal' }),
186	    /AbortSignal/,
187	  );
188	});
189	
190	test('legal input under an already-aborted signal keeps the existing cancelled result', async () => {
191	  const controller = new AbortController();
192	  controller.abort();
193	  let businessCalls = 0;
194	  let compensationCalls = 0;
195	  const callerInput = { amount: 5 };
196	  const execution = await executeWorkflowAsync(businessWorkflow(), callerInput, {
197	    opA: () => { businessCalls += 1; return 'A'; },
198	    undoA: () => { compensationCalls += 1; return 'u'; },
199	  }, { signal: controller.signal });
200	
201	  assert.equal(execution.status, 'cancelled');
202	  assert.deepEqual(execution.trace, []);
203	  assert.deepEqual(execution.actionAttempts, []);
204	  assert.equal(execution.compensationStatus, 'not_needed');
205	  assert.deepEqual(execution.compensationAttempts, []);
206	  assert.deepEqual(execution.context.input, { amount: 5 });
207	  assert.equal(businessCalls, 0);
208	  assert.equal(compensationCalls, 0);
209	  execution.context.input.amount = 999;
210	  assert.deepEqual(callerInput, { amount: 5 });
211	});
