213	// ---------------------------------------------------------------------------
214	// Shared memory placed only where cloning drops it never condemns legal data
215	// ---------------------------------------------------------------------------
216	
217	test('shared bytes in dropped properties (Date/RegExp/ArrayBuffer/Error auxiliaries, non-enumerable and symbol keys) are accepted', async () => {
218	  const symbolKey = Symbol('hidden');
219	
220	  const date = new Date('2021-06-07T08:09:10.000Z');
221	  date.aux = new SharedArrayBuffer(8);
222	
223	  const regexp = /pattern/gi;
224	  regexp.aux = new SharedArrayBuffer(8);
225	
226	  const plainBuffer = new ArrayBuffer(2);
227	  plainBuffer.dropped = new SharedArrayBuffer(2);
228	
229	  const errorWithAux = new Error('boom');
230	  errorWithAux.details = new SharedArrayBuffer(4);
