// Host values structuredClone rebuilds from internal slots rather than as an
// ordinary property bag: Date, RegExp, ArrayBuffer and byte views, errors,
// boxed primitives and Blob/File/CryptoKey-style leaves. Map and Set are
// handled separately (their entries must keep the graph's reference
// identities). A value that reaches the run input has already passed an
// independentCopy at reception, so every object here is a real clone
// product and this classification only tells cloneInputGraph which objects
// must be recreated as host leaves instead of plain objects — it mirrors the
// branches containsSharedMemory walks.
function isHostCloneLeaf(value) {
  if (nodeTypes.isDate(value) || nodeTypes.isRegExp(value)
    || nodeTypes.isBoxedPrimitive(value)
    || nodeTypes.isArrayBuffer(value) || nodeTypes.isSharedArrayBuffer(value)
    || nodeTypes.isTypedArray(value) || nodeTypes.isDataView(value)
    || nodeTypes.isNativeError(value)) {
    return true;
  }
  for (const constructor of HOST_LEAF_CONSTRUCTORS) {
    if (isInstanceOfGuarded(value, constructor)) return true;
  }
  return false;
}

// Copies the live run input for delivery to a business attempt, a
// compensation attempt, or a compensation snapshot captured at an action's
// success moment.
//
// The run input starts as an ordinary structured clone (cloneRunInput), so
// reception-time behavior is unchanged: own properties the caller attached
// to a Date (or any other host leaf) were dropped there. During the run,
// though, a successful form can attach a missing field to such an object —
// request.createdAt is a Date and a default for request.createdAt.channel
// lands as an own enumerable property on the Date, and a multi-level path
// creates plain parent objects on it. A plain structuredClone of that input
// would silently drop the property again (a Date clones only its internal
// time), so the business action and compensation would read an input that
// disagrees with context.input and with the conditions: defaults the run had
// already successfully applied would vanish precisely from the delivered
// copies. This cloner therefore recreates each host leaf with
// structuredClone — keeping the Date's type and original time value (a
// subclass keeps the cloned subclass), a RegExp's pattern, an Error's cause,
// buffer bytes and so on — and then re-attaches the leaf's own enumerable
// properties, which can only be content a form added after reception.
//
// Plain objects, arrays, Map entries and Set members are rebuilt manually so
// every structured-clone reference relationship survives: circular paths and
// two fields that pointed at the same object (including the same Date) still
// point at one shared object within each copy. Every produced object is
// fresh, so a business action or compensation rewriting the Date's time, a
// defaulted field or a form-created parent object can never reach the run
// input, the caller's input, another run or the next retry attempt — each
// delivery gets a complete independent copy as of its own capture moment.
function cloneInputGraph(source) {
  const copies = new Map();

  // Creates target as source's clone, records the mapping before any child
  // is copied (so a cycle through an attached property resolves to the new
  // object), and copies source's own enumerable string-keyed properties —
  // exactly the property set structuredClone retains on ordinary objects
  // and arrays, and exactly the set a form path can ever add.
  const adopt = (original, target) => {
    copies.set(original, target);
    for (const key of Object.keys(original)) {
      target[key] = clone(original[key]);
    }
    return target;
  };

  // Host leaf: structuredClone reproduces its internal state (and its
  // retained content such as an Error's non-enumerable cause) exactly as a
  // direct clone would; the adopt step only restores properties that clone
  // discards — the own properties successful forms attached during the run.
  const hostLeaf = original => adopt(original, structuredClone(original));

  const clone = original => {
    if (original === null || typeof original !== 'object') return original;
    const existing = copies.get(original);
    if (existing !== undefined) return existing;

    if (Array.isArray(original)) {
      // Enumerable indices (holes stay holes) plus enumerable non-index
      // properties, precisely as structuredClone treats arrays.
      return adopt(original, new Array(original.length));
    }
    if (nodeTypes.isMap(original)) {
      const map = new Map();
      copies.set(original, map);
      for (const [key, value] of original) map.set(clone(key), clone(value));
