      // own properties the entry clone above discards.
      for (const key of Object.keys(original)) map[key] = clone(original[key]);
      return map;
    }
    if (nodeTypes.isSet(original)) {
      const set = new Set();
      copies.set(original, set);
      for (const value of original) set.add(clone(value));
      for (const key of Object.keys(original)) set[key] = clone(original[key]);
      return set;
    }
    if (isHostCloneLeaf(original)) return hostLeaf(original);
    // Plain objects and arbitrary class instances both clone as ordinary
    // objects — including a Date or another host value a form converted into
    // a parent by attaching an own property (that cannot happen: a host leaf
    // stays branded; this branch covers every ordinary property bag).
    return adopt(original, {});
  };

  return clone(source);
}

// Runs an operation under a retry policy — the one attempt loop shared by
// business actions and compensations. Every invocation works on fresh
// structured-clone argument copies produced by prepareArgs, so mutations by
// a failed attempt are discarded before the next try; a thrown exception, a
// rejected Promise, a return value carrying shared memory (a
// SharedArrayBuffer or a byte view over one, anywhere in the saved graph),
// or a return value that cannot be structured-cloned all count as a failed
// attempt. Shared memory is rejected explicitly: cloning it "succeeds" but
// keeps sharing the underlying bytes with an object the implementation can

