1342	// default created). A restored value that points back at retained content
1343	// reuses the identity map, so two input fields that pointed at the same Date
1344	// still point at one copied Date inside each copy. Every produced object is
1345	// fresh, so a business action or compensation rewriting the received Date's
1346	// time, a defaulted field or a form-created parent can never reach the run
1347	// input, the caller's input, another run or the next retry — each delivery
1348	// is a complete independent copy as of its own capture moment.
1349	function cloneInputGraph(source) {
1350	  const clonedRoot = structuredClone(source);
1351	  // original object -> the object the single structuredClone produced for it
1352	  const paired = new Map();
1353	
1354	  // Pairs the own enumerable children a non-leaf container retains, key by
1355	  // key (arrays reach this through their enumerable non-index properties;
1356	  // their indexed slots are aligned positionally by `pair`). Keys absent
